ST.xhtml:
// ============================================================
// Tc2_DataExchange.stLibVersion_Tc2_DataExchange 演示程序
// ============================================================
// 注意：项目须引用 Tc2_DataExchange 与 Tc2_System（ST_LibVersion / F_CmpLibVersion）
// 验证步骤：
//   1. 编译 + 登录
//   2. 在线监视 stMyVer.iMajor/iMinor/iBuild — 应显示 1.2.2
//   3. 在线监视 bOk — 应为 TRUE
// ============================================================

stMyVer := stLibVersion_Tc2_DataExchange;

bOk := F_CmpLibVersion(
    stLibVersion := stLibVersion_Tc2_DataExchange,
    iMajor       := 1,
    iMinor       := 2,
    iBuild       := 2,
    iRevision    := 0,
    nCmpType     := E_CmpLibVersion.GreaterOrEqual
);
